        return text.startsWith('Rule 1001') || text.startsWith('Part I') || text.startsWith('Part II') || text.startsWith('Part III') || text.startsWith('Part IV') || text.startsWith('Part V') || text.startsWith('Part VI') || text.startsWith('Part VII') || text.startsWith('Part VIII') || text.startsWith('Part IX') || text.startsWith('[Part X');
    });
    // Get unique hrefs
    const seen = new Set();
    const uniqueLinks = [];
    for (const link of targetLinks) {
        const href = link.href;
        if (!seen.has(href)) {
            seen.add(href);
            uniqueLinks.push({
                text: link.textContent.trim(),
                href: href
            });
        }
    }
    return uniqueLinks;
}"}

