    const mainUl = document.querySelector('article ul');
    if (!mainUl) return [];
    const topLevelItems = Array.from(mainUl.children).filter(child => child.tagName === 'LI');
    const results = [];
    for (const item of topLevelItems) {
        // Get the text nodes that are direct children, before any nested list
        let heading = '';
        for (const node of item.childNodes) {
            if (node.nodeType === Node.TEXT_NODE) {
                heading += node.textContent;
            } else if (node.tagName === 'UL') {
                // stop at first nested list
                break;
            } else {
                // might be a link or other inline element, include its text
                heading += node.textContent;
            }
