                if (node.nodeType === Node.TEXT_NODE && node.textContent.trim().startsWith('PART')) {
                    partTitle = node.textContent.trim();
                    break;
                }
            }
            if (!partTitle) partTitle = text.split('\n')[0].trim();
            // Find nested ul for rules
            const ruleUl = li.querySelector('ul');
            const rules = [];
            if (ruleUl) {
                const ruleLis = ruleUl.querySelectorAll('li');
                for (let ruleLi of ruleLis) {
                    // Get the text of the link or the li
                    const ruleText = ruleLi.textContent.trim();
                    if (ruleText.startsWith('Rule')) {
                        rules.push(ruleText);
                    }
                }
            }
            parts.push({ part: partTitle, rules });
        }
    }
    return parts;
}"}

